# Check what each value maps to
input_values = set()
output_values = set()
for row in input_grid:
    for val in row:
        input_values.add(val)
for row in output_grid:
    for val in row:
        output_values.add(val)

print(f"Input values: {sorted(input_values)}")
print(f"Output values: {sorted(output_values)}")

# Build mapping
mapping = {}
for r, (in_row, out_row) in enumerate(zip(input_grid, output_grid)):
    for i, (inv, outv) in enumerate(zip(in_row, out_row)):
        if inv not in mapping:
            mapping[inv] = {}
        if outv not in mapping[inv]:
            mapping[inv][outv] = 0
        mapping[inv][outv] += 1

print(f"\nMapping per input value:")
for inv in sorted(mapping.keys()):
    print(f"  Input {inv}: {mapping[inv]}")

# Test the simple swap rule: 5->7, 7->0
def test_swap(v):
    if v == 5:
        return 7
    elif v == 7:
        return 0
    return v

print("\nTesting 5->7, 7->0 rule:")
all_match = True
for r, (in_row, out_row) in enumerate(zip(input_grid, output_grid)):
    for i, (inv, outv) in enumerate(zip(in_row, out_row)):
        expected = test_swap(inv)
        if expected != outv:
            print(f"Mismatch at row {r}, col {i}: input={inv}, expected={expected}, got={outv}")
            all_match = False
if all_match:
    print("All match! Rule: 5->7, 7->0")
